mapper.select:
SELECT COUNT(1)
FROM ticket_order
WHERE ticket_category_id = #{ticketCategoryId}

mapper.update:
UPDATE ticket_order
SET
    status = #{newStatus},
    cancel_time = #{cancelTime},
    cancel_reason = #{cancelReason},
    updated_at = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = #{oldStatus}

UPDATE ticket_order
SET
    status = #{newStatus},
    pay_time = #{payTime},
    updated_at = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = #{oldStatus}
